<template>
  <div class="space-y-5">
    <div class="breadcrumbs text-sm"><ul><li><NuxtLink to="/">Home</NuxtLink></li><li><NuxtLink to="/system-audits">System audit</NuxtLink></li><li>Tender case file</li></ul></div>
    <div v-if="loading" class="flex justify-center py-20"><span class="loading loading-spinner loading-lg" /></div>
    <div v-else-if="errorMessage" class="alert alert-error"><Icon name="lucide:triangle-alert" class="h-5 w-5" />{{ errorMessage }}</div>
    <template v-else-if="record">
      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body gap-5 p-6"><div class="flex flex-col justify-between gap-4 lg:flex-row"><div class="max-w-3xl"><div class="flex flex-wrap gap-2"><span class="font-mono text-xs text-base-content/55">{{ record.tender.tendernumber || 'Tender number pending' }}</span><span class="badge badge-success badge-sm">{{ label(record.tender.status) }}</span><span v-if="isConsultancy" class="badge badge-outline badge-sm"><Icon name="lucide:briefcase-business" class="h-3.5 w-3.5" />EOI + RFP</span></div><h1 class="mt-2 text-2xl font-bold">{{ record.tender.title }}</h1><p class="mt-2 text-sm leading-6 text-base-content/60">{{ record.tender.description }}</p></div><div class="rounded-box border border-base-200 bg-base-200/40 p-4 text-sm"><p class="font-semibold">{{ record.tender.company?.name }}</p><p class="mt-1 text-base-content/55">{{ record.tender.procurement_method?.name || 'Method not set' }}</p><p v-if="record.tender.procurement_group?.name" class="mt-1 text-xs font-medium text-base-content/50">{{ record.tender.procurement_group.name }}</p></div></div><div class="grid gap-3 border-t border-base-200 pt-5 sm:grid-cols-4"><div><p class="text-xs text-base-content/50">Created</p><p class="mt-1 font-semibold">{{ dateTime(record.tender.created_at) }}</p></div><div><p class="text-xs text-base-content/50">Published</p><p class="mt-1 font-semibold">{{ dateTime(record.tender.published_at) }}</p></div><div><p class="text-xs text-base-content/50">APP lines</p><p class="mt-1 font-semibold">{{ record.source_app_items?.length || 0 }}</p></div><div><p class="text-xs text-base-content/50">Audit events</p><p class="mt-1 font-semibold">{{ record.timeline?.length || 0 }}</p></div></div></div></section>

      <section class="card card-border bg-base-100 shadow-sm"><div class="card-body gap-0 p-0">
        <div class="border-b border-base-200 p-5"><div class="flex flex-wrap justify-between gap-3"><div><h2 class="card-title text-lg">{{ caseFileTitle }}</h2><p class="mt-1 text-sm text-base-content/55">{{ caseFileDescription }}</p></div><span class="badge badge-outline">{{ completeCount }} stages complete</span></div></div>
        <div class="p-4 lg:hidden"><label class="mb-2 block text-xs font-medium text-base-content/55" for="system-audit-step">Process step</label><select id="system-audit-step" v-model="activeStepKey" class="select w-full"><option v-for="step in record.process_steps" :key="step.key" :value="step.key">{{ label(step.status) }} — {{ step.title }}</option></select></div>
        <div class="grid min-h-[36rem] lg:grid-cols-[19rem_minmax(0,1fr)]"><aside class="hidden border-r border-base-200 bg-base-200/25 p-3 lg:block"><div class="sticky top-4"><ul class="menu menu-sm w-full gap-1"><li v-for="(step, index) in record.process_steps" :key="step.key"><button type="button" :class="{ 'menu-active': activeStepKey === step.key }" @click="activeStepKey = step.key"><span :class="['grid h-7 w-7 shrink-0 place-items-center rounded-full text-xs font-bold', activeStepKey === step.key ? 'bg-base-100/20' : 'bg-base-200']">{{ index + 1 }}</span><span class="min-w-0 flex-1 text-left"><span class="block whitespace-normal font-semibold leading-5">{{ step.title }}</span><span class="mt-0.5 block text-xs opacity-60">{{ label(step.status) }}</span></span><Icon v-if="step.status === 'COMPLETE'" name="lucide:circle-check" class="h-4 w-4 shrink-0 text-success" /></button></li></ul></div></aside>
          <article v-if="activeStep" class="min-w-0 p-5 sm:p-6"><header class="flex flex-col justify-between gap-4 border-b border-base-200 pb-5 sm:flex-row sm:items-start"><div><div class="flex flex-wrap items-center gap-2"><Icon :name="stepIcon(activeStep.key)" class="h-5 w-5 text-base-content/55" /><h2 class="text-xl font-bold">{{ activeStep.title }}</h2></div><p class="mt-2 max-w-3xl text-sm leading-6 text-base-content/55">{{ activeStep.description }}</p></div><div class="flex shrink-0 items-center gap-2"><span :class="['badge badge-sm', stepBadge(activeStep.status)]">{{ label(activeStep.status) }}</span><span v-if="activeStep.completed_at" class="text-xs text-base-content/45">{{ dateTime(activeStep.completed_at) }}</span></div></header><div class="my-5 flex flex-wrap gap-2"><span v-for="(value, key) in activeStep.summary" :key="key" class="badge badge-ghost"><strong class="mr-1">{{ valueText(value) }}</strong>{{ label(key) }}</span></div><div v-if="['submissions', 'rfp-submissions'].includes(activeStep.key)" class="overflow-x-auto"><table class="table table-sm"><thead><tr><th>{{ isConsultancy ? 'Consultant' : 'Bidder' }}</th><th>Status</th><th>Submitted</th><th class="text-right">Evidence</th></tr></thead><tbody><tr v-for="bid in activeStep.records.bids" :key="bid.uuid"><td>{{ bid.supplier?.name || (isConsultancy ? 'Unknown consultant' : 'Unknown bidder') }}</td><td>{{ label(bid.status) }}</td><td>{{ dateTime(bid.submitted_at) }}</td><td class="text-right"><button class="btn btn-sm" :disabled="!bid.response_available" @click="openResponse(bid)"><Icon name="lucide:eye" class="h-4 w-4" />{{ bid.response_available ? 'View response' : 'Not opened' }}</button></td></tr></tbody></table></div><AuditEvidence v-else :value="activeStep.records" /></article>
        </div>
      </div></section>
    </template>

    <dialog ref="responseDialog" class="modal"><div class="modal-box max-w-6xl"><div class="flex justify-between gap-4"><div><h2 class="text-xl font-bold">Opened bidder response</h2><p class="mt-1 text-sm text-base-content/55">{{ selectedBid?.supplier?.name }} · read-only evidence</p></div><form method="dialog"><button class="btn btn-sm btn-circle btn-ghost">✕</button></form></div><div v-if="responseLoading" class="flex justify-center py-16"><span class="loading loading-spinner loading-lg" /></div><div v-else-if="responseError" class="alert alert-error mt-5">{{ responseError }}</div><div v-else-if="responseRecord" class="mt-5 space-y-4"><div v-if="!responseRecord.available" class="alert alert-warning">{{ responseRecord.reason }}</div><template v-else><div class="alert alert-info text-sm"><Icon name="lucide:shield-check" class="h-5 w-5" />Opened content only; encryption keys and sealed envelopes remain protected.</div><details class="collapse collapse-arrow border border-base-200" open><summary class="collapse-title font-semibold">Technical response</summary><div class="collapse-content"><AuditEvidence :value="responseRecord.technical_response" /></div></details><details class="collapse collapse-arrow border border-base-200"><summary class="collapse-title font-semibold">Financial response</summary><div class="collapse-content"><AuditEvidence :value="responseRecord.financial_response" /></div></details><details class="collapse collapse-arrow border border-base-200"><summary class="collapse-title font-semibold">Evaluation responses</summary><div class="collapse-content"><AuditEvidence :value="responseRecord.evaluations" /></div></details></template></div></div><form method="dialog" class="modal-backdrop"><button>Close</button></form></dialog>
  </div>
</template>

<script setup>
definePageMeta({ layout: 'default' }); useHead({ title: 'Tender audit case file' })
const route = useRoute(); const api = useSystemAuditHelper(); const { can } = useCheckPermission()
const loading = ref(true); const errorMessage = ref(''); const record = ref(null); const activeStepKey = ref(''); const responseDialog = ref(null); const responseLoading = ref(false); const responseError = ref(''); const responseRecord = ref(null); const selectedBid = ref(null)
const completeCount = computed(() => record.value?.process_steps?.filter(step => step.status === 'COMPLETE').length || 0)
const isConsultancy = computed(() => record.value?.tender?.audit_profile === 'CONSULTANCY_RFP_EOI')
const caseFileTitle = computed(() => isConsultancy.value ? 'Consultancy selection case file' : 'Procurement case file')
const caseFileDescription = computed(() => isConsultancy.value ? 'Trace the Terms of Reference through EOI qualification, RFP proposals, evaluation, negotiations and award.' : 'Select a statutory process step to inspect its complete audit evidence.')
const activeStep = computed(() => record.value?.process_steps?.find(step => step.key === activeStepKey.value) || record.value?.process_steps?.[0] || null)
const label = value => String(value || '').replaceAll('_', ' ').toLowerCase().replace(/\b\w/g, letter => letter.toUpperCase())
const valueText = value => typeof value === 'boolean' ? (value ? 'Yes' : 'No') : value
const dateTime = value => value ? new Intl.DateTimeFormat('en-ZW', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—'
const stepBadge = status => ({ COMPLETE: 'badge-success', IN_PROGRESS: 'badge-warning', PENDING: 'badge-ghost', NOT_APPLICABLE: 'badge-ghost' }[status] || 'badge-ghost')
const stepIcon = key => ({ planning: 'lucide:clipboard-list', 'eoi-notice': 'lucide:megaphone', 'eoi-opening': 'lucide:mail-open', 'eoi-evaluation': 'lucide:list-checks', 'rfp-issue': 'lucide:send', 'rfp-submissions': 'lucide:inbox', 'rfp-opening': 'lucide:folder-open', 'rfp-evaluation': 'lucide:chart-no-axes-combined', negotiations: 'lucide:handshake', 'approval-publication': 'lucide:stamp', 'clarifications-addenda': 'lucide:messages-square', submissions: 'lucide:send', opening: 'lucide:folder-open', evaluation: 'lucide:clipboard-check', spoc: 'lucide:landmark', award: 'lucide:award', 'record-history': 'lucide:history' }[key] || 'lucide:file-text')
const openResponse = async bid => { selectedBid.value = bid; responseRecord.value = null; responseError.value = ''; responseLoading.value = true; responseDialog.value?.showModal(); const { data, error } = await api.getBidResponse(route.params.uuid, bid.uuid); responseLoading.value = false; if (error || data?.status === false) responseError.value = error?.data?.message || data?.message || 'The bidder response could not be loaded.'; else responseRecord.value = data.data }
onMounted(async () => { if (!can('can.access.systemaudits')) { errorMessage.value = 'You do not have permission to view system audits.'; loading.value = false; return } const { data, error } = await api.getTender(route.params.uuid); loading.value = false; if (error || data?.status === false) errorMessage.value = error?.data?.message || data?.message || 'Tender audit case file could not be loaded.'; else { record.value = data.data; activeStepKey.value = data.data.process_steps?.find(step => step.status === 'IN_PROGRESS')?.key || data.data.process_steps?.[0]?.key || '' } })
</script>
